diff --git a/src/main/java/org/xbill/DNS/Compression.java b/src/main/java/org/xbill/DNS/Compression.java
index 5effa800..21bf9922 100644
--- a/src/main/java/org/xbill/DNS/Compression.java
+++ b/src/main/java/org/xbill/DNS/Compression.java
@@ -51,0 +52,21 @@ public class Compression {
+  /**
+   * Removes a compression entry mapping of a name in a message.
+   *
+   * @param name The name to remove.
+   * @since 3.6.6
+   */
+  public void remove(Name name) {
+    int row = (name.hashCode() & 0x7FFFFFFF) % TABLE_SIZE;
+    for (Entry entry = table[row], prev = null; entry != null; prev = entry, entry = entry.next) {
+      if (entry.name.equals(name)) {
+        if (prev == null) {
+          table[row] = entry.next;
+        } else {
+          prev.next = entry.next;
+        }
+        log.trace("Removed {}", name);
+        return;
+      }
+    }
+  }
+
